    if (toggleBtn) toggleBtn.style.display = 'none';
    document.body.style.overflow = 'hidden';

    // ★ 注入物品中文名称（放在iconContainer内，替代svg）
    if (state.hideInventoryIcons) setTimeout(() => injectItemNames(), 300);
